const fs = require('fs');
const path = require('path');

const rootDir = process.cwd();
const apiDir = path.join(rootDir, 'api');
const sourceEnv = path.join(rootDir, '.env.production');
const targetEnv = path.join(apiDir, '.env.production');

if (!fs.existsSync(apiDir)) {
  fs.mkdirSync(apiDir, { recursive: true });
}

if (fs.existsSync(sourceEnv)) {
  fs.copyFileSync(sourceEnv, targetEnv);
  console.log('[postbuild] Copied .env.production -> api/.env.production');
} else if (!fs.existsSync(targetEnv)) {
  fs.writeFileSync(
    targetEnv,
    '# Generated by postbuild. Add production env vars here.\n',
    'utf8',
  );
  console.warn(
    '[postbuild] .env.production not found at project root. Created api/.env.production placeholder.',
  );
} else {
  console.log('[postbuild] api/.env.production already exists.');
}

